import numpy as np

def inp(agent=None, movers=(), rewards=(), prev=True, border=True):
    x = np.zeros(500)
    if border:
        for r in range(10):
            for c in range(10):
                if r in (0,9) or c in (0,9):
                    x[(r*10+c)*5+3] = 1.0
    if agent is not None:
        x[(agent[0]*10+agent[1])*5+0] = 1.0
    for m in movers:
        x[(m[0]*10+m[1])*5+1] = 1.0
    for rw in rewards:
        x[(rw[0]*10+rw[1])*5+2] = 1.0
    if prev:  # stationary previous frame: agent + movers were there last step
        if agent is not None:
            x[(agent[0]*10+agent[1])*5+4] = 1.0
        for m in movers:
            x[(m[0]*10+m[1])*5+4] = 1.0
    return x

