def make_obs(agent=None, mover=None, reward=None, prev=None):
    x = np.zeros(500, dtype=float)
    # wall border in obstacle channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r * 10 + c) * 5 + 3] = 1.0
    if agent is not None:
        x[(agent[0] * 10 + agent[1]) * 5 + 0] = 1.0
    if mover is not None:
        x[(mover[0] * 10 + mover[1]) * 5 + 1] = 1.0
    if reward is not None:
        x[(reward[0] * 10 + reward[1]) * 5 + 2] = 1.0
    if prev is None:
        prev = []
        if agent is not None:
            prev.append(agent)
        if mover is not None:
            prev.append(mover)
    for r, c in prev:
        x[(r * 10 + c) * 5 + 4] = 1.0
    return x

