import numpy as np

def idx(r, c, ch):
    return (r * 10 + c) * 5 + ch

def make_state(agent, ball, prev_ball):
    X = np.zeros((1, 500))
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                X[0, idx(r, c, 3)] = 1.0
    ar, ac = agent
    X[0, idx(ar, ac, 0)] = 1.0
    if ball is not None:
        br, bc = ball
        X[0, idx(br, bc, 1)] = 1.0
    # previous frame: previous agent (same as current) and previous ball
    X[0, idx(ar, ac, 4)] = 1.0
    if prev_ball is not None:
        pr, pc = prev_ball
        X[0, idx(pr, pc, 4)] = 1.0
    return X

