actions = np.argmax(logits, axis=1)
act_names = ['noop', 'up', 'down', 'left', 'right']

print("agent=(4,1), ball col/row/velocity -> action [up_logit, down_logit, noop_logit]")
for i, (col, r, vel, prev_r) in enumerate(labels):
